<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {refreshAll} from '$app/navigation';
  import {command,request,display} from '#lib/client/api.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  import Status from './Status.svelte';
  import ReferencePicker from './ReferencePicker.svelte';
  import PrivacyControls from './PrivacyControls.svelte';
  let {data}:{data:AppData}=$props();
  let tab:'erasure'|'retention'|'holds'|'purposes'=$state('erasure');
  let kind=$state('document'),objectId=$state(''),reason=$state(''),password=$state(''),approvalPassword=$state('');
  let busy=$state(false),error=$state(''),notice=$state(''),current:Row|null=$state(null),approved=$state(false);
  const jobs=$derived((data.related?.deletion_jobs||[]) as Row[]);
  const decision=$derived.by(()=>current?.decision);
  const blockers=$derived(Array.isArray(decision?.blockers)?decision.blockers as string[]:null);
  const canApprove=$derived.by(()=>current?.status==='requested'&&blockers!==null&&!blockers.length);
  async function submit(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';notice='';try{await request('/api/v1/reauth',{password});current=await command('privacy.erasure.request',undefined,{...(kind==='document'?{document_id:objectId}:{party_id:objectId}),reason});approved=false;notice='Der Antrag wurde aufgenommen. Die tatsächlichen Fristen, Zwecke und Sperren stehen in der Prüfung unten.';reason='';password='';objectId='';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Der Antrag konnte nicht aufgenommen werden.';}finally{busy=false;}}
  async function review(job:Row){if(busy)return;busy=true;error='';notice='';try{current=await command('privacy.erasure.review',job.id,{},job.version);approved=false;approvalPassword='';notice='Die Prüfung wurde aus dem aktuellen Serverbestand neu ermittelt.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Prüfung konnte nicht aktualisiert werden.';}finally{busy=false;}}
  async function approve(event:SubmitEvent){event.preventDefault();if(!current||!approved||!canApprove||busy)return;busy=true;error='';notice='';try{await request('/api/v1/reauth',{password:approvalPassword});await command('privacy.erasure.approve',current.id,{},current.version);current=null;approvalPassword='';approved=false;notice='Die konkrete Entfernung wurde freigegeben. Der gesonderte Dienst prüft Fristen und Sperren vor der Ausführung erneut und dokumentiert das Ergebnis.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Entfernung ist noch nicht freigabefähig.';}finally{busy=false;}}
  function openJob(job:Row){current=job;approved=false;approvalPassword='';error='';notice='';}
</script>
<p class="privacy-intro">Dokumentieren Sie tatsächliche Zwecke, geprüfte Aufbewahrungsfristen und rechtliche Sperren. Eine Entfernung wird für jedes konkrete Objekt gesondert geprüft und nachvollziehbar ausgeführt.</p>
<nav class="subnav privacy-nav" aria-label="Datenschutzaufgaben">{#each [{id:'erasure' as const,label:'Entfernung prüfen'},{id:'purposes' as const,label:'Zwecke'},{id:'retention' as const,label:'Aufbewahrung'},{id:'holds' as const,label:'Rechtliche Sperren'}] as item}<button class:active={tab===item.id} aria-current={tab===item.id?'page':undefined} onclick={()=>tab=item.id}>{item.label}</button>{/each}</nav>
{#if tab!=='erasure'}{#key tab}<PrivacyControls {data} mode={tab}/>{/key}{:else}
{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div>{/if}
<div class="settings-grid"><section class="panel"><header class="panel-header"><div><h2>Ein konkretes Objekt zur Prüfung aufnehmen</h2><p>Ein Antrag entfernt noch keine Daten.</p></div><Icon name="lock" size={18}/></header><form class="panel-body" onsubmit={submit}><fieldset disabled={busy}><div class="field mb"><label for="privacy-kind">Was soll geprüft werden? *</label><select use:searchableSelect={kind} id="privacy-kind" bind:value={kind} onchange={()=>objectId=''}><option value="document">Ein Dokument mit seinen Ableitungen</option><option value="party">Ein Geschäftspartnerprofil</option></select></div><div class="field mb"><label for="privacy-object">Konkretes {kind==='document'?'Dokument':'Geschäftspartnerprofil'} *</label>{#key kind}<ReferencePicker id="privacy-object" bind:value={objectId} reference={kind==='document'?'documents':'parties'} initial={data.lookups[kind==='document'?'documents':'parties']||[]} required/>{/key}<span class="field-help">Suchen Sie den Namen oder die Belegnummer und wählen Sie den tatsächlichen Eintrag aus.</span></div><div class="field mb"><label for="privacy-reason">Zweck, Umfang und Begründung des Antrags *</label><textarea id="privacy-reason" bind:value={reason} required minlength="10"></textarea><span class="field-help">Beschreiben Sie, weshalb dieses konkrete Objekt nicht mehr benötigt wird und welcher Umfang geprüft werden soll.</span></div><div class="field"><label for="privacy-password">Eigene Passphrase bestätigen *</label><input id="privacy-password" type="password" bind:value={password} autocomplete="current-password" required/></div><button class="btn primary full mt">Antrag zur Frist- und Sperrprüfung aufnehmen</button></fieldset></form></section>
<section class="panel"><header class="panel-header"><div><h2>Gespeicherte Anträge</h2><p>Ein Ergebnis oder ein konkreter Sperrgrund bleibt sichtbar.</p></div></header><div class="panel-body">{#each jobs as job}<article class="privacy-job"><div><h3>{job.document_id?'Dokumentprüfung':'Geschäftspartnerprüfung'} vom {display(job.created_at,'date')}</h3><Status value={job.status}/></div><p>{job.reason}</p>{#if job.status==='requested'}<button class="btn small mt" disabled={busy} onclick={()=>openJob(job)}>Prüfergebnis und nächsten Schritt ansehen</button>{:else if job.status==='completed'}<p class="field-help mt">Ausführung dokumentiert{job.decision?.removedFiles!==undefined?` · ${job.decision.removedFiles} Dateifassungen entfernt`:''}{job.decision?.sharedFilesPreserved?.length?` · ${job.decision.sharedFilesPreserved.length} gemeinsam genutzte Originale für weitere berechtigte Akten erhalten`:''}.</p>{:else}<p class="field-help mt">Freigabe und tatsächliche Ausführung werden getrennt nachgewiesen. <a class="text-link" href="/jobs">Verarbeitung prüfen</a></p>{/if}</article>{/each}{#if !jobs.length}<p class="small">Noch keine berechtigten Prüfanträge vorhanden. Ein neuer Antrag wird zuerst auf tatsächliche Zwecke, Fristen und Sperren geprüft.</p>{/if}</div></section></div>
{#if current}<section class="panel mt"><header class="panel-header"><div><h2>Konkretes Prüfergebnis</h2><p>{current.document_id?'Dokument mit ermittelten Ableitungen':'Geschäftspartnerprofil'} · {display(current.created_at,'created_at')}</p></div><Status value={current.status}/></header><div class="panel-body"><div class="action-preview"><p class="small">{current.reason}</p></div>{#if blockers===null}<div class="notice warning"><Icon name="alert"/><div>Für diesen älteren Antrag ist noch kein vollständiges Prüfergebnis hinterlegt. Ermitteln Sie den aktuellen Stand vor einer Entscheidung.</div></div>{:else if blockers.length}<div class="notice warning"><Icon name="lock"/><div><strong>Entfernung derzeit gesperrt</strong><ul>{#each blockers as blocker}<li>{blocker}</li>{/each}</ul><p class="field-help mt">Prüfen Sie den genannten Zweck, die Aufbewahrung oder die rechtliche Sperre im passenden Bereich. Eine Frist wird durch diesen Antrag nicht verkürzt.</p></div></div>{:else}<div class="notice info"><Icon name="check"/><div>Die aktuelle Prüfung hat keine gespeicherten Sperrgründe ermittelt. Eine tatsächliche Entfernung benötigt die ausdrückliche Freigabe unten.</div></div>{/if}
<dl class="definition-list"><div><dt>Letzte Prüfung</dt><dd>{decision?.reviewedAt?display(decision.reviewedAt,'updated_at'):'Noch nicht ermittelt'}</dd></div>{#if current.document_id}<div><dt>Ermittelte Dokumente einschließlich Ableitungen</dt><dd>{decision?.documentIds?.length??'Noch nicht ermittelt'}</dd></div><div><dt>Betroffene Originalversionen</dt><dd>{decision?.versionIds?.length??'Noch nicht ermittelt'}</dd></div><div><dt>Exklusive Dateifassungen zur Entfernung</dt><dd>{decision?.files?.length??'Noch nicht ermittelt'}</dd></div><div class="full"><dt>Für weitere berechtigte Akten erhaltene Originale</dt><dd>{decision?.sharedFiles?.length??'Noch nicht ermittelt'}</dd></div>{/if}</dl><div class="inline-actions mt"><button class="btn" disabled={busy} onclick={()=>current&&review(current)}><Icon name="refresh" size={15}/>Fristen & Sperren erneut prüfen</button><button class="btn" disabled={busy} onclick={()=>current=null}>Prüfung schließen</button></div>
{#if canApprove}<form class="form-section" onsubmit={approve}><h3>Die konkrete Entfernung freigeben</h3><label class="check-field mb"><input type="checkbox" bind:checked={approved} required/><span>Ich habe Zuständigkeit, benanntes Objekt, Umfang und das aktuelle Prüfergebnis kontrolliert. Die bezeichneten exklusiven Daten dürfen entfernt werden.</span></label><div class="field"><label for="privacy-approve-password">Eigene Passphrase erneut bestätigen *</label><input id="privacy-approve-password" type="password" bind:value={approvalPassword} autocomplete="current-password" required/></div><button class="btn danger mt" disabled={busy||!approved}>Konkrete Entfernung verbindlich freigeben</button><p class="field-help mt">Der Löschdienst dokumentiert die Ausführung getrennt und prüft vorab erneut auf inzwischen entstandene Sperren.</p></form>{/if}</div></section>{/if}
{/if}
<style>.privacy-intro{font-size:13px;line-height:1.8;max-width:90ch;margin-bottom:21px}.privacy-nav{gap:8px}.privacy-nav button{font-size:12px;min-height:42px;padding:9px 14px;border:1px solid transparent;border-radius:5px;white-space:nowrap;color:var(--muted)}.privacy-nav button:hover{background:var(--wash)}.privacy-nav button.active{border-color:var(--line);background:var(--paper);color:var(--forest)}fieldset{border:0;padding:0;margin:0;min-width:0}.privacy-job+.privacy-job{border-top:1px solid var(--line);padding-top:23px;margin-top:23px}.privacy-job>div{display:flex;justify-content:space-between;align-items:start;gap:15px}.privacy-job h3{font-size:14px;font-weight:550}.privacy-job>p{font-size:13px;margin-top:10px;overflow-wrap:anywhere}.notice ul{padding-left:20px;margin-top:10px}.notice li+li{margin-top:5px}@media(max-width:760px){.privacy-intro,.privacy-job>p{font-size:14px}.privacy-nav button{font-size:13px;min-height:48px}.privacy-job>div{flex-wrap:wrap;gap:9px}}</style>
